-- Chronal Tributes 90-93 (items 980001-980035, cloned from item 56300). Rerunnable. Needs shared_memory and a zone restart.
-- Stock EQEmu servers get IDs 90-93, so the rules at the end set Custom:ChronalTributeFirstID/LastID to 90/99.
DELETE FROM tribute_levels WHERE tribute_id BETWEEN 90 AND 93;
DELETE FROM tributes WHERE id BETWEEN 90 AND 93;
DELETE FROM items WHERE id BETWEEN 980000 AND 980099;
DROP TEMPORARY TABLE IF EXISTS sink_item;
CREATE TEMPORARY TABLE sink_item SELECT * FROM items WHERE id = 56300;
