INSERT INTO tributes (id, unknown, name, descr, isguild) VALUES (90, 5, 'Chronal Might', 'Strength drawn from Fractures you have already closed sharpens your blows.<br>Works only inside a Greater Rift. Tiers stack: tier III also turns on I and II, so it works in rift tiers 1-300, giving the benefit of the rift''s band. Instead of a cost every 10 minutes, it takes 100 favor x the rift tier once per run, on entering the rift. The cost shown is for the top of the band.<br>Benefit -<br>I (rift tiers 1-100): 5 Attack, 3 Heroic Strength, 3 Heroic Dexterity, 50 HP<br>II (rift tiers 101-200): 10 Attack, 6 Heroic Strength, 6 Heroic Dexterity, 100 HP<br>III (rift tiers 201-300): 15 Attack, 9 Heroic Strength, 9 Heroic Dexterity, 150 HP<br>IV (rift tiers 301-400): 20 Attack, 12 Heroic Strength, 12 Heroic Dexterity, 200 HP<br>V (rift tiers 401-500): 25 Attack, 15 Heroic Strength, 15 Heroic Dexterity, 250 HP', 0);
