INSERT INTO tributes (id, unknown, name, descr, isguild) VALUES (91, 5, 'Chronal Arcana', 'The unspent magic of collapsed timelines answers your spells.<br>Works only inside a Greater Rift. Tiers stack: tier III also turns on I and II, so it works in rift tiers 1-300, giving the benefit of the rift''s band. Instead of a cost every 10 minutes, it takes 100 favor x the rift tier once per run, on entering the rift. The cost shown is for the top of the band.<br>Benefit -<br>I (rift tiers 1-100): 10 Spell Damage, 10 Heal Amount, 50 Mana, 3 Heroic Intelligence, 3 Heroic Wisdom<br>II (rift tiers 101-200): 20 Spell Damage, 20 Heal Amount, 100 Mana, 6 Heroic Intelligence, 6 Heroic Wisdom<br>III (rift tiers 201-300): 30 Spell Damage, 30 Heal Amount, 150 Mana, 9 Heroic Intelligence, 9 Heroic Wisdom<br>IV (rift tiers 301-400): 40 Spell Damage, 40 Heal Amount, 200 Mana, 12 Heroic Intelligence, 12 Heroic Wisdom<br>V (rift tiers 401-500): 50 Spell Damage, 50 Heal Amount, 250 Mana, 15 Heroic Intelligence, 15 Heroic Wisdom', 0);
